// Command gen_vectors emits reference vectors for drpc.wire by running
// storj.io/drpc itself.
//
// Not part of the library; nothing under src/ links Go. The framing is simple
// enough that a self-consistent implementation is easy to write and easy to
// get subtly wrong — the control byte packs three things into eight bits, and
// a Kind shifted by the wrong amount still round-trips through one's own
// codec. Asking the reference implementation what the bytes are removes that
// whole class of agreement-with-oneself.
//
//	cd testdata && go run gen_vectors.go
package main

import (
	"encoding/hex"
	"fmt"

	"storj.io/drpc/drpcwire"
)

func emit(name string, b []byte) {
	fmt.Printf(" :%-26s %q\n", name, hex.EncodeToString(b))
}

func frame(kind drpcwire.Kind, stream, message uint64, done, control bool, data []byte) drpcwire.Frame {
	return drpcwire.Frame{
		Data:    data,
		ID:      drpcwire.ID{Stream: stream, Message: message},
		Kind:    kind,
		Done:    done,
		Control: control,
	}
}

func main() {
	fmt.Println("{;; generated by testdata/gen_vectors.go — do not hand-edit")

	// one control byte per kind, so a Kind shifted wrongly cannot pass
	for _, k := range []struct {
		name string
		kind drpcwire.Kind
	}{
		{"invoke", drpcwire.KindInvoke},
		{"message", drpcwire.KindMessage},
		{"error", drpcwire.KindError},
		{"cancel", drpcwire.KindCancel},
		{"close", drpcwire.KindClose},
		{"close-send", drpcwire.KindCloseSend},
		{"invoke-metadata", drpcwire.KindInvokeMetadata},
	} {
		emit("kind-"+k.name,
			drpcwire.AppendFrame(nil, frame(k.kind, 1, 1, true, false, []byte{0x2a})))
	}

	// the three control-byte flags, independently
	emit("flags-none", drpcwire.AppendFrame(nil, frame(drpcwire.KindMessage, 1, 1, false, false, []byte{0x2a})))
	emit("flags-done", drpcwire.AppendFrame(nil, frame(drpcwire.KindMessage, 1, 1, true, false, []byte{0x2a})))
	emit("flags-control", drpcwire.AppendFrame(nil, frame(drpcwire.KindMessage, 1, 1, false, true, []byte{0x2a})))
	emit("flags-both", drpcwire.AppendFrame(nil, frame(drpcwire.KindMessage, 1, 1, true, true, []byte{0x2a})))

	// multi-byte varints in every position
	emit("big-ids", drpcwire.AppendFrame(nil,
		frame(drpcwire.KindMessage, 300, 70000, true, false, []byte{0x01, 0x02})))
	emit("empty-data", drpcwire.AppendFrame(nil,
		frame(drpcwire.KindClose, 5, 9, true, false, nil)))
	long := make([]byte, 200)
	for i := range long {
		long[i] = byte(i)
	}
	emit("long-data", drpcwire.AppendFrame(nil,
		frame(drpcwire.KindMessage, 2, 3, true, false, long)))

	// an invoke as it actually appears: the body is the rpc name
	emit("invoke-piecestore", drpcwire.AppendFrame(nil,
		frame(drpcwire.KindInvoke, 1, 1, true, false,
			[]byte("/piecestore.Piecestore/Upload"))))

	// two frames back to back — a reader must find both
	two := drpcwire.AppendFrame(nil, frame(drpcwire.KindInvoke, 1, 1, true, false, []byte("/a/B")))
	two = drpcwire.AppendFrame(two, frame(drpcwire.KindMessage, 1, 2, true, false, []byte{0x08, 0x96, 0x01}))
	emit("two-frames", two)

	// a packet split across frames by SplitN, then the packet it reassembles to
	var split []byte
	payload := make([]byte, 10)
	for i := range payload {
		payload[i] = byte(0xf0 + i)
	}
	err := drpcwire.SplitN(drpcwire.Packet{
		Data: payload,
		ID:   drpcwire.ID{Stream: 7, Message: 4},
		Kind: drpcwire.KindMessage,
	}, 4, func(fr drpcwire.Frame) error {
		split = drpcwire.AppendFrame(split, fr)
		return nil
	})
	if err != nil {
		panic(err)
	}
	emit("split-3-frames", split)
	emit("split-payload", payload)

	fmt.Printf(" :%-26s %d\n", "split-default-size", 64*1024)
	fmt.Println("}")
}
